<template><view class="page"><view v-if="!isAdmin" class="card"><view class="h">管理员登录</view><input v-model="code" password placeholder="请输入管理员口令"/><button class="btn" @click="login">登录</button><view class="muted tip">管理员身份由云函数校验，请勿在客户端硬编码权限。</view></view><block v-else><view class="tabs"><text :class="{on:tab==='vehicles'}" @click="tab='vehicles'">车辆库存</text><text :class="{on:tab==='contracts'}" @click="tab='contracts'">签约履约</text></view><view v-if="tab==='vehicles'"><view class="card form"><input v-model="vehicle.brand" placeholder="品牌"/><input v-model="vehicle.series" placeholder="车系"/><input v-model="vehicle.year" placeholder="年份"/><input v-model="vehicle.mileage" placeholder="里程（万公里）"/><input v-model="vehicle.color" placeholder="车身颜色"/><textarea v-model="vehicle.condition" placeholder="车况描述"/><input v-model="vehicle.price" placeholder="售价"/><input v-model="vehicle.monthlyPayment" placeholder="月供（展示用）"/><button class="btn" @click="saveVehicle">新增车辆</button></view><view v-for="v in vehicles" :key="v._id" class="card row">{{v.brand}} {{v.series}} · ¥{{v.price}} <button size="mini" @click="toggle(v)">{{v.status==='on'?'下架':'上架'}}</button><button size="mini" type="warn" @click="remove(v)">删除</button></view></view><view v-else><view class="card form"><input v-model="contract.customerName" placeholder="客户姓名"/><input v-model="contract.phone" placeholder="联系电话"/><input v-model="contract.idNo" placeholder="身份证号"/><input v-model="contract.contractNo" placeholder="合同编号"/><input v-model="contract.vehicleId" placeholder="车辆ID"/><input v-model="contract.monthlyPayment" placeholder="每期月供"/><picker :range="statuses" @change="contract.status=statuses[$event.detail.value]"><view>履约状态：{{contract.status}}</view></picker><button class="btn" @click="saveContract">新增合同</button></view><button class="btn export" @click="exportCsv">导出还款台账CSV</button><view v-for="c in contracts" :key="c._id" class="card">{{c.customerName}} · {{c.contractNo}} · <text class="tag">{{c.status}}</text></view></view></block></view></template>
<script setup>import {ref,onMounted} from 'vue';const db=wx.cloud.database(),isAdmin=ref(false),code=ref(''),tab=ref('vehicles'),vehicles=ref([]),contracts=ref([]),statuses=['正常履约','逾期','结清','解约收回车辆'];const vehicle=ref({status:'on'}),contract=ref({status:statuses[0]});async function login(){const r=await wx.cloud.callFunction({name:'api',data:{action:'adminLogin',code:code.value}});if(r.result?.ok){isAdmin.value=true;load()}else uni.showToast({title:'无权限',icon:'none'})}async function load(){vehicles.value=(await db.collection('vehicles').get()).data;contracts.value=(await db.collection('contracts').get()).data}async function saveVehicle(){await db.collection('vehicles').add({data:{...vehicle.value,price:Number(vehicle.value.price),plan:{monthlyPayment:Number(vehicle.value.monthlyPayment)},createdAt:db.serverDate()}});vehicle.value={status:'on'};load()}async function toggle(v){await db.collection('vehicles').doc(v._id).update({data:{status:v.status==='on'?'off':'on'}});load()}async function remove(v){await db.collection('vehicles').doc(v._id).remove();load()}async function saveContract(){await db.collection('contracts').add({data:{...contract.value,createdAt:db.serverDate()}});contract.value={status:statuses[0]};load()}async function exportCsv(){const r=await db.collection('repayments').get();const csv=['期数,应还日期,应还金额,实际还款日期,实还金额,...r.data.map(x=>[x.period,x.dueDate,x.dueAmount,x.paidDate||'',x.paidAmount||'',].join(','))].join('\n');uni.setClipboardData({data:csv});uni.showToast({title:'CSV已复制，可粘贴到Excel'})}onMounted(()=>{})</script><style scoped>.h{font-size:36rpx;font-weight:600;margin-bottom:18rpx}.tabs{display:flex;background:#fff;padding:20rpx;border-radius:12rpx;margin-bottom:20rpx}.tabs text{flex:1;text-align:center}.tabs .on{color:#1677ff;font-weight:600}.form input,.form textarea{display:block;width:100%;box-sizing:border-box;background:#f5f6f8;padding:18rpx;margin:12rpx 0;border-radius:8rpx}.form textarea{height:140rpx}.row{display:flex;align-items:center;gap:10rpx}.row button{margin-left:auto}.row button+button{margin-left:0}.export{margin-bottom:20rpx}.tip{margin-top:18rpx}</style>
